import { iterateIDs, lowerID } from 'core/id-parser';

// Only matches squads created in the same log chain as the creator's initialization, i.e. autogenerated squads.
export default {
  regex:
    /^\[([0-9.:-]+)]\[([ 0-9]*)]LogSquad: (.+) \(Online IDs:([^)]+)\) has created Squad (\d+) \(Squad Name: (.+)\) on (.+)/,
  onMatch: (args, logParser) => {
    const chainID = +args[2];
    const IDs = {};
    iterateIDs(args[4]).forEach((platform, id) => {
      IDs[lowerID(platform)] = id;
    });

    const initialized = logParser.eventStore.initializedPlayers;
    if (initialized?.[chainID] !== args[3]) return;
    delete initialized[chainID];

    logParser.emit('AUTO_SQUAD_CREATED', {
      raw: args[0],
      time: args[1],
      chainID,
      playerName: args[3],
      squadID: args[5],
      squadName: args[6],
      teamName: args[7],
      ...IDs
    });
  }
};
